#include <bits/stdc++.h>
using namespace std;
struct Line {int a,b,c; bool operator==(Line const&o)const{return a==o.a&&b==o.b&&c==o.c;}};
struct LH {size_t operator()(Line const&x)const noexcept{return ((uint64_t)(x.a+100)<<42)^((uint64_t)(x.b+100)<<32)^(uint32_t)(x.c+100000);}};
static vector<int> pairline; static vector<unsigned char> lcount; static vector<int> touched; static int triples[1771];
Line canon(int x1,int y1,int x2,int y2){int A=y2-y1,B=x1-x2,C=A*x1+B*y1;int g=gcd(abs(A),gcd(abs(B),abs(C)));if(g){A/=g;B/=g;C/=g;}if(A<0||(A==0&&B<0)){A=-A;B=-B;C=-C;}return {A,B,C};}
void init_lines(){unordered_map<Line,int,LH> ids;ids.reserve(240000);pairline.assign(900*900,-1);int next=0;for(int u=0;u<900;u++){int x1=u/30,y1=u%30;for(int v=u+1;v<900;v++){Line L=canon(x1,y1,v/30,v%30);auto[it,ins]=ids.emplace(L,next);if(ins)next++;int id=it->second;pairline[u*900+v]=pairline[v*900+u]=id;}}lcount.assign(next,0);touched.reserve(1770);memset(triples,0,sizeof(triples));for(int k=0;k<=60;k++)triples[k*(k-1)/2]=k*(k-1)*(k-2)/6;}
string encode(vector<int>const&r,vector<int>const&b){string s;for(int x:r)s.push_back((char)x);for(int x:b)s.push_back((char)x);return s;}
int potential(string const&s){int cells[60];for(int i=0;i<30;i++){cells[2*i]=i*30+(unsigned char)s[i]-1;cells[2*i+1]=i*30+(unsigned char)s[30+i]-1;}touched.clear();for(int i=0;i<60;i++)for(int j=i+1;j<60;j++){int id=pairline[cells[i]*900+cells[j]];if(lcount[id]++==0)touched.push_back(id);}int ans=0;for(int id:touched){ans+=triples[lcount[id]];lcount[id]=0;}return ans;}
bool legal(string const&s,int l,int i,int j){int o=30*l,q=30*(1-l);return (unsigned char)s[o+j]!=(unsigned char)s[q+i]&&(unsigned char)s[o+i]!=(unsigned char)s[q+j];}
string apply_move(string s,string const&m){int l=m[0]=='b';auto c=m.find(':'),q=m.find(',');int i=stoi(m.substr(c+1,q-c-1))-1,j=stoi(m.substr(q+1))-1;assert(legal(s,l,i,j));swap(s[30*l+i],s[30*l+j]);return s;}
pair<size_t,bool> component(string const&start,int B,int target){unordered_set<string>seen;seen.reserve(100000);queue<string>q;seen.insert(start);q.push(start);bool lower=false;while(!q.empty()){string s=move(q.front());q.pop();for(int l=0;l<2;l++)for(int i=0;i<30;i++)for(int j=i+1;j<30;j++){if(!legal(s,l,i,j))continue;string z=s;swap(z[30*l+i],z[30*l+j]);if(seen.count(z))continue;int p=potential(z);if(p>B)continue;if(p<target)lower=true;seen.insert(z);q.push(move(z));}}return {seen.size(),lower};}
int main(int argc,char**argv){init_lines();
vector<int>r6={19,15,26,18,23,17,8,2,25,13,9,4,20,28,1,12,7,24,29,5,3,30,27,11,14,6,21,16,22,10},b6={12,10,23,9,7,15,26,6,21,1,20,2,8,29,30,16,27,25,3,11,14,18,4,5,22,28,24,13,17,19};
vector<string>m65={"r:1,6","r:6,18","b:8,11","b:6,8","b:6,18","r:2,6","b:18,27","b:7,23","b:2,26","b:2,8","r:2,13","r:1,4","b:13,27","r:3,7","b:7,27","b:23,27","r:1,4","r:3,13","b:3,27","r:7,12","b:12,23","r:8,12","r:8,26","r:21,26","b:19,24","b:20,27"}; vector<int>p65={6,7,7,8,10,10,10,9,9,10,7,9,10,8,10,10,9,10,10,9,9,8,10,9,8,8,5};
vector<string>m54={"r:20,24","b:3,23","b:24,27","b:19,20","b:3,8","b:3,9","r:8,14","b:19,23","r:21,24","r:2,14","r:2,26","r:2,30","r:21,30","r:21,24","b:3,23","r:3,27","b:23,27","b:11,23","r:24,30","r:2,30","r:2,26","r:21,24","r:2,11","r:2,30","r:6,30","b:2,6","r:2,30","b:4,11","r:4,6","b:4,22","b:22,27","r:3,27"}; vector<int>p54={5,7,10,10,9,10,9,10,9,10,10,9,10,10,10,9,10,10,8,10,8,10,10,10,10,9,10,7,10,10,10,8,4};
string s=encode(r6,b6);assert(potential(s)==6);assert(p65.size()==m65.size()+1);for(size_t i=0;i<m65.size();i++){s=apply_move(s,m65[i]);assert(potential(s)==p65[i+1]);}assert(potential(s)==5);string s5=s;assert(p54.size()==m54.size()+1);for(size_t i=0;i<m54.size();i++){s=apply_move(s,m54[i]);assert(potential(s)==p54[i+1]);}assert(potential(s)==4);string s4=s;
int mode=argc>1?atoi(argv[1]):0;if(mode==0){cout<<"AC p31 barrier-ten extension replay\n"<<"six_to_five_moves: 26\n"<<"five_to_four_moves: 32\n"<<"final_potential: 4\n";return 0;}
vector<tuple<int,int,size_t>> checks;string start;int target;if(mode==6){start=encode(r6,b6);target=6;checks={{6,6,1},{6,7,9},{6,8,33},{6,9,860}};}else if(mode==5){start=s5;target=5;checks={{5,6,2},{5,7,18},{5,8,68},{5,9,501}};}else if(mode==4){start=s4;target=4;checks={{4,5,2},{4,6,10},{4,7,29},{4,8,286},{4,9,2033}};}else return 2;size_t total=0;for(auto[t,B,n]:checks){auto[got,low]=component(start,B,target);assert(got==n);assert(!low);total+=got;cerr<<"target="<<t<<" B="<<B<<" states="<<got<<"\n";}cout<<"AC p31 exact lower components\n"<<"checkpoint: "<<mode<<"\n"<<"checks: "<<checks.size()<<"\n"<<"states_total: "<<total<<"\n";}
